export const expandedEntries=Object.entries(groups).flatMap(([category,raw])=>raw.trim().split('\n').map(row=>{
 const [title,body,practice]=row.split('|');
 return {id:'guide-'+title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/-$/,''),title,category,body,aliases:[],source:'https://en.wikipedia.org/wiki/'+references[category],sections:[{title:'In practice',body:practice}]};
}));
